<?php
declare(strict_types=1); require_once __DIR__.'/../bootstrap.php'; Auth::requireApprovedSeller();
$pdo=db(); $sellerId=(int)Auth::userId();
$stmt=$pdo->prepare('SELECT DISTINCT o.id,o.order_number,o.total,o.status,o.created_at,u.name customer_name,COUNT(oi.id) item_count FROM orders o INNER JOIN order_items oi ON oi.order_id=o.id INNER JOIN users u ON u.id=o.customer_id WHERE oi.seller_id=? GROUP BY o.id,o.order_number,o.total,o.status,o.created_at,u.name ORDER BY o.id DESC');$stmt->execute([$sellerId]);$orders=$stmt->fetchAll();
function sellerBadge(string $s):string{return match($s){'completed'=>'success','cancelled','refunded'=>'danger','shipped'=>'info',default=>'warning'};}
?>
<!doctype html><html lang="en"><head><link rel="icon" href="<?= e(url('/assets/images/favicon-32.png')) ?>"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Orders · DogoFlow Seller</title><?php require __DIR__.'/../partials/tailwind.php'; ?></head><body class="seller-page"><main class="container-wide seller-shell-df"><?php $sellerActive = 'orders'; require __DIR__ . '/../partials/seller_header.php'; ?><section class="seller-page-heading-df" style="padding-top:32px;margin-bottom:22px"><div><span class="eyebrow-df">Store operations</span><h1>Orders</h1><p>Manage orders containing products from your store.</p></div></section><section class="card overflow-hidden"><div class="table-wrap-df"><table class="table-df"><thead><tr><th>Order</th><th>Customer</th><th>Your items</th><th>Order total</th><th>Status</th><th>Date</th><th></th></tr></thead><tbody><?php foreach($orders as $o):?><tr><td><strong><?=e($o['order_number'])?></strong></td><td><?=e($o['customer_name'])?></td><td><?=number_format((int)$o['item_count'])?></td><td>GH₵ <?=number_format((float)$o['total'],2)?></td><td><span class="badge-df <?=e(sellerBadge((string)$o['status']))?>"><?=e(ucwords(str_replace('_',' ',$o['status'])))?></span></td><td><?=e(date('d M Y',strtotime($o['created_at'])))?></td><td><a class="btn-df secondary" href="<?=e(url('/seller/order.php?id='.(int)$o['id']))?>">Manage</a></td></tr><?php endforeach;if(!$orders):?><tr><td colspan="7"><div class="empty-df">No orders for your store yet.</div></td></tr><?php endif;?></tbody></table></div></section></main></body></html>